<?php
$q=param('q');$staff=rows('SELECT * FROM petugas WHERE nama_petugas LIKE ? OR no_telepon LIKE ? ORDER BY nama_petugas',["%$q%","%$q%"]);
$edit=param('edit')?row('SELECT * FROM petugas WHERE id_petugas=?',[(int)param('edit')]):null;
heading('','Petugas','Kelola nama, peran, dan nomor telepon petugas.',modalButton('Tambah petugas','petugas-form','users'));
?>
<section class="panel"><div class="panel-head"><div><h2>Daftar petugas <span class="count-pill"><?=count($staff)?></span></h2><p>Petugas dipilih saat transaksi dicatat</p></div><form class="inline-search" method="get"><input type="hidden" name="page" value="petugas"><label class="search-field"><?=icon('search')?><input name="q" value="<?=e($q)?>" aria-label="Cari petugas" placeholder="Cari nama atau telepon"></label><button class="button secondary">Cari</button></form></div><?php if(!$staff):emptyState('Petugas tidak ditemukan');else:?><div class="table-wrap"><table><thead><tr><th>Petugas</th><th>Peran</th><th>Nomor telepon</th><th>ID petugas</th><th>Tindakan</th></tr></thead><tbody><?php foreach($staff as $s):?><tr><td><div class="person"><span class="avatar person-avatar"><?=e(mb_strtoupper(mb_substr($s['nama_petugas'],0,1)))?></span><strong><?=e($s['nama_petugas'])?></strong></div></td><td><?=badge($s['role_petugas'])?></td><td><?=e($s['no_telepon'])?></td><td class="muted">PG-<?=str_pad((string)$s['id_petugas'],3,'0',STR_PAD_LEFT)?></td><td><div class="row-actions"><?=linkButton('Edit',url('petugas',['edit'=>$s['id_petugas'],'open'=>'petugas-form']),'edit','secondary small')?><?=actionForm('petugas_delete','petugas',['id_petugas'=>$s['id_petugas']],'Hapus','trash',true)?></div></td></tr><?php endforeach;?></tbody></table></div><?php endif;?></section>
<?php beginDialog('petugas-form',$edit?'Edit petugas':'Tambah petugas','Petugas yang memiliki riwayat transaksi tidak dapat dihapus.','petugas_save','petugas');echo '<input type="hidden" name="id_petugas" value="'.e($edit['id_petugas']??'').'">';field('nama_petugas','Nama lengkap',$edit['nama_petugas']??'');selectField('role_petugas','Peran',array_combine(['Admin','Inbound Checker','Outbound Sorter'],['Admin','Inbound Checker','Outbound Sorter']),$edit['role_petugas']??'');field('no_telepon','Nomor telepon',$edit['no_telepon']??'','tel',true,20);endDialog();?>
